package com.wajahatnaeem.oneplusota.data

/**
 * Oplus OTA gateways (update/v3). URLs + RSA public keys.
 * id: 0 = Global(SG), 1 = China, 2 = India, 3 = Europe
 */
object OplusServers {
    data class Server(val id: Int, val name: String, val url: String, val pubKeyB64: String, val negotiationVersion: String)

    val all: List<Server> = listOf(
        Server(0, "GL (Singapore)", "https://component-otapc-sg.allawnos.com/update/v3",
            "",
            "1615895993238"),
        Server(1, "CN", "https://component-otapc-cn.allawntech.com/update/v3",
            "",
            "1615879139745"),
        Server(2, "IN", "https://component-otapc-in.allawnos.com/update/v3",
            "",
            "1615896309308"),
        Server(3, "EU", "https://component-otapc-eu.allawnos.com/update/v3",
            "",
            "1615897067573"),
    )

    fun byId(id: Int): Server = all.firstOrNull { it.id == id } ?: all[0]

    /** Same-region gateway first, then the others (used by the fallback source). */
    fun othersThan(id: Int): List<Server> = all.filter { it.id != id }
}
